    "The big store." to Tr(ja = "おおきな デパート。", fr = "Le grand magasin.", de = "Das große Kaufhaus.", it = "Il grande magazzino.", es = "Los grandes almacenes.", zh = "那家大商店。"),
    "CELADON DEPT. STORE 4F sells FIRE, THUNDER, WATER and LEAF STONES. MOON STONES are found, e.g. in MT. MOON." to Tr(ja = "タマムシデパートの 4かいで ほのおのいし かみなりのいし みずのいし リーフのいしを うっています。 つきのいしは オツキミやま などで ひろえます。", fr = "Le 3e étage du CENTRE COMMERCIAL de CELADOPOLE vend PIERRE FEU, PIERREFOUDRE, PIERRE EAU et PIERREPLANTE. Les PIERRES LUNE se ramassent, par exemple au MONT SELENITE.", de = "Im 3. Stock des PRISMANIA EINKAUFSZENTRUMs gibt es FEUERSTEIN, DONNERSTEIN, WASSERSTEIN und BLATTSTEIN. MONDSTEINE findet man z. B. am MONDBERG.", it = "Il 3º piano del CENTRO COMMERCIALE di AZZURROPOLI vende PIETRAFOCAIA, PIETRATUONO, PIETRAIDRICA e PIETRAFOGLIA. La PIETRALUNARE si trova in giro, per esempio al MONTE LUNA.", es = "La planta 3 del CENTRO COMERCIAL de AZULONA vende PIEDRA FUEGO, PIEDRATRUENO, PIEDRA AGUA y PIEDRA HOJA. Las PIEDRAS LUNARES se encuentran, por ejemplo, en el MT. MOON.", zh = "玉虹百货 4 楼出售火之石、雷之石、水之石、叶之石。月之石要自己找，比如月见山。"),
    "MOVE DELETER" to Tr(ja = "わざを わすれさせる ひと", fr = "EFFACEUR DE CAPACITES", de = "ATTACKEN-VERLERNER", it = "ELIMINAMOSSE", es = "QUITA-MOVIMIENTOS", zh = "招式删除师"),
    "A house in FUCHSIA CITY." to Tr(ja = "セキチクシティの いえ。", fr = "Une maison de PARMANIE.", de = "Ein Haus in FUCHSANIA CITY.", it = "Una casa di FUCSIAPOLI.", es = "Una casa de CIUDAD FUCSIA.", zh = "浅红市的一栋房子。"),
    "MOVE RELEARNER" to Tr(ja = "わざを おもいださせる ひと", fr = "DINGUE DES CAPACITES", de = "POKéMON-ATTACKEN-MANIAC", it = "ESPERTO MOSSE", es = "TUTOR de MOVIMIENTOS", zh = "招式教学者"),
    "A house on TWO ISLAND. Bring a BIG MUSHROOM or two TINY MUSHROOMS." to Tr(ja = "2のしまの いえ。 おおきなキノコ 1こか ちいさなキノコ 2こを もっていこう。", fr = "Une maison de l'ILE 2. Apportez un GROS CHAMPI ou deux PETITS CHAMPIS.", de = "Ein Haus auf EILAND ZWEI. Bring einen RIESENPILZ oder zwei MINIPILZE mit.", it = "Una casa di SECONDISOLA. Porta un GRANDE FUNGO o due MINIFUNGHI.", es = "Una casa de ISLA SECUNDA. Lleva una SETA GRANDE o dos MINI SETAS.", zh = "二之岛的一栋房子。带一个大蘑菇或两个小蘑菇。"),
    "EEVEE" to Tr(ja = "イーブイ", fr = "EVOLI", de = "EVOLI", it = "EEVEE", es = "EEVEE", zh = "伊布"),
    "CELADON CITY." to Tr(ja = "タマムシシティ。", fr = "CELADOPOLE.", de = "PRISMANIA CITY.", it = "AZZURROPOLI.", es = "CIUDAD AZULONA.", zh = "玉虹市。"),
    "The rooftop room of the CELADON CONDOMINIUMS - reached by the back entrance." to Tr(ja = "タマムシマンションの おくじょうの へや。 うらぐちから いけます。", fr = "La pièce sur le toit du MANOIR CELADON, par l'entrée de derrière.", de = "Das Dachzimmer der PRISMANIA-VILLA, über den Hintereingang.", it = "La stanza sul tetto di VILLAZZURRA, dall'ingresso sul retro.", es = "La habitación de la azotea de la MANSIÓN AZULONA, por la entrada trasera.", zh = "玉虹公寓的顶层房间——从后门进去。"),
    "LAPRAS" to Tr(ja = "ラプラス", fr = "LOKHLASS", de = "LAPRAS", it = "LAPRAS", es = "LAPRAS", zh = "拉普拉斯"),
    "SAFFRON CITY." to Tr(ja = "ヤマブキシティ。", fr = "SAFRANIA.", de = "SAFFRONIA CITY.", it = "ZAFFERANOPOLI.", es = "CIUDAD AZAFRÁN.", zh = "金黄市。"),
    "An employee on SILPH CO. 7F, after you reach him during the ROCKET takeover." to Tr(ja = "ロケットだんに のっとられた シルフカンパニーの 7かいで しゃいんの ところへ いくと くれます。", fr = "Un employé au 6e étage de la SYLPHE SARL, quand vous le rejoignez pendant l'occupation ROCKET.", de = "Ein Angestellter im 6. Stock der SILPH CO., wenn du ihn während der ROCKET-Besetzung erreichst.", it = "Un impiegato al 6º piano della SILPH SpA, quando lo raggiungi durante l'occupazione ROCKET.", es = "Un empleado de la planta 6 de SILPH S.A., cuando llegas hasta él durante la ocupación ROCKET.", zh = "西尔佛公司 7楼的一名员工，要在火箭队占领期间见到他。"),
    "HITMONLEE / HITMONCHAN" to Tr(ja = "サワムラー / エビワラー", fr = "KICKLEE / TYGNON", de = "KICKLEE / NOCKCHAN", it = "HITMONLEE / HITMONCHAN", es = "HITMONLEE / HITMONCHAN", zh = "飞腿郎 / 快拳郎"),
    "Next to a gym." to Tr(ja = "ジムの となり。", fr = "À côté d'une ARENE.", de = "Neben einer ARENA.", it = "Accanto a una PALESTRA.", es = "Junto a un GIMNASIO.", zh = "道馆旁边。"),
    "Beat the FIGHTING DOJO in SAFFRON CITY and pick one." to Tr(ja = "ヤマブキシティの かくとうどうじょうで かって 1ぴき えらびます。", fr = "Battez le DOJO KARATE de SAFRANIA et choisissez-en un.", de = "Besiege das KAMPF-DOJO in SAFFRONIA CITY und wähle eines.", it = "Sconfiggi il DOJO KARATE di ZAFFERANOPOLI e scegline uno.", es = "Vence en el DOJO-KARATE de CIUDAD AZAFRÁN y elige uno.", zh = "打赢金黄市的格斗道场，二选一。"),
    "Fossils" to Tr(ja = "カセキ", fr = "Fossiles", de = "Fossilien", it = "Fossili", es = "Fósiles", zh = "化石"),
    "A cave, a museum, and a lab." to Tr(ja = "どうくつ、 はくぶつかん、 けんきゅうじょ。", fr = "Une grotte, un musée et un labo.", de = "Eine Höhle, ein Museum und ein Labor.", it = "Una grotta, un museo e un laboratorio.", es = "Una cueva, un museo y un laboratorio.", zh = "一处洞窟、一座博物馆、一个研究所。"),
    "Pick the HELIX or DOME FOSSIL in MT. MOON; the OLD AMBER is in the back of PEWTER's museum. The CINNABAR ISLAND lab revives them." to Tr(ja = "オツキミやまで かいのカセキか こうらのカセキを えらびます。 ひみつのコハクは ニビかがくはくぶつかんの おくに あります。 グレンじまの けんきゅうじょで ふっかつ できます。", fr = "Choisissez le NAUTILE ou le FOSSILE DOME au MONT SELENITE ; le VIEIL AMBRE est au fond du MUSEE d'ARGENTA. Le LABO de CRAMOIS'ILE les ranime.", de = "Nimm am MONDBERG das HELIXFOSSIL oder das DOMFOSSIL; der ALTBERNSTEIN liegt hinten im MUSEUM von MARMORIA CITY. Das LABOR auf der ZINNOBERINSEL belebt sie wieder.", it = "Scegli l'HELIXFOSSILE o il DOMOFOSSILE al MONTE LUNA; l'AMBRA ANTICA è in fondo al MUSEO di PLUMBEOPOLI. Il LABORATORIO dell'ISOLA CANNELLA li riporta in vita.", es = "Elige el FÓSIL HELIX o el FÓSIL DOMO en el MT. MOON; el ÁMBAR VIEJO está al fondo del MUSEO de PLATEADA. El LABORATORIO de ISLA CANELA los revive.", zh = "在月见山选贝壳化石或甲壳化石；秘密琥珀在尼比博物馆深处。红莲岛的研究所可以复活它们。"),
    "GAME CORNER prizes" to Tr(ja = "ゲームコーナーの けいひん", fr = "Lots du CASINO", de = "SPIELHALLEN-Preise", it = "Premi del CASINÒ", es = "Premios del CASINO", zh = "游戏城奖品"),
    "Win coins in CELADON CITY." to Tr(ja = "タマムシシティで コインを かせごう。", fr = "Gagnez des jetons à CELADOPOLE.", de = "Gewinne Münzen in PRISMANIA CITY.", it = "Vinci gettoni ad AZZURROPOLI.", es = "Gana fichas en CIUDAD AZULONA.", zh = "在玉虹市赢代币。"),
    "The prize corner next to the CELADON CITY GAME CORNER trades coins for POKéMON: ABRA Lv9 (180 coins), CLEFAIRY Lv8 (500), DRATINI Lv18 (2800), SCYTHER Lv25 (5500), PORYGON Lv26 (9999). A man in the CELADON CITY restaurant gives you the COIN CASE." to Tr(ja = "タマムシシティの ゲームコーナーの となりの けいひん こうかんじょで コインと ポケモンを こうかん できます: ケーシィ Lv9 (180まい)、 ピッピ Lv8 (500)、 ミニリュウ Lv18 (2800)、 ストライク Lv25 (5500)、 ポリゴン Lv26 (9999)。 コインケースは タマムシシティの しょくどうに いる おとこの ひとが くれます。", fr = "Le comptoir des lots, à côté du CASINO de CELADOPOLE, échange des jetons contre des POKéMON : ABRA N.9 (180 jetons), MELOFEE N.8 (500), MINIDRACO N.18 (2800), INSECATEUR N.25 (5500), PORYGON N.26 (9999). Un homme du RESTAURANT de CELADOPOLE vous donne la BOITE JETONS.", de = "Die Preisbörse neben der SPIELHALLE in PRISMANIA CITY tauscht Münzen gegen POKéMON: ABRA Lv.9 (180 Münzen), PIEPI Lv.8 (500), DRATINI Lv.18 (2800), SICHLOR Lv.25 (5500), PORYGON Lv.26 (9999). Ein Mann im RESTAURANT von PRISMANIA CITY gibt dir den MÜNZKORB.", it = "Il banco premi accanto al CASINÒ di AZZURROPOLI scambia gettoni con POKéMON: ABRA Lv.9 (180 gettoni), CLEFAIRY Lv.8 (500), DRATINI Lv.18 (2800), SCYTHER Lv.25 (5500), PORYGON Lv.26 (9999). Un uomo nel RISTORANTE di AZZURROPOLI ti dà il SALVADANAIO.", es = "La tienda de premios junto al CASINO de CIUDAD AZULONA cambia fichas por POKéMON: ABRA Nv.9 (180 fichas), CLEFAIRY Nv.8 (500), DRATINI Nv.18 (2800), SCYTHER Nv.25 (5500), PORYGON Nv.26 (9999). Un hombre del RESTAURANTE de CIUDAD AZULONA te da el MONEDERO.", zh = "游戏城隔壁的奖品柜台可以用代币换宝可梦：凯西 Lv9（180 枚）、皮皮 Lv8（500）、迷你龙 Lv18（2800）、飞天螳螂 Lv25（5500）、多边兽 Lv26（9999）。玉虹市餐厅里有个人会给你代币盒。"),
    "The prize corner next to the CELADON CITY GAME CORNER trades coins for POKéMON: ABRA Lv7 (120 coins), CLEFAIRY Lv12 (750), PINSIR Lv18 (2500), DRATINI Lv24 (4600), PORYGON Lv18 (6500). A man in the CELADON CITY restaurant gives you the COIN CASE." to Tr(ja = "タマムシシティの ゲームコーナーの となりの けいひん こうかんじょで コインと ポケモンを こうかん できます: ケーシィ Lv7 (120まい)、 ピッピ Lv12 (750)、 カイロス Lv18 (2500)、 ミニリュウ Lv24 (4600)、 ポリゴン Lv18 (6500)。 コインケースは タマムシシティの しょくどうに いる おとこの ひとが くれます。", fr = "Le comptoir des lots, à côté du CASINO de CELADOPOLE, échange des jetons contre des POKéMON : ABRA N.7 (120 jetons), MELOFEE N.12 (750), SCARABRUTE N.18 (2500), MINIDRACO N.24 (4600), PORYGON N.18 (6500). Un homme du RESTAURANT de CELADOPOLE vous donne la BOITE JETONS.", de = "Die Preisbörse neben der SPIELHALLE in PRISMANIA CITY tauscht Münzen gegen POKéMON: ABRA Lv.7 (120 Münzen), PIEPI Lv.12 (750), PINSIR Lv.18 (2500), DRATINI Lv.24 (4600), PORYGON Lv.18 (6500). Ein Mann im RESTAURANT von PRISMANIA CITY gibt dir den MÜNZKORB.", it = "Il banco premi accanto al CASINÒ di AZZURROPOLI scambia gettoni con POKéMON: ABRA Lv.7 (120 gettoni), CLEFAIRY Lv.12 (750), PINSIR Lv.18 (2500), DRATINI Lv.24 (4600), PORYGON Lv.18 (6500). Un uomo nel RISTORANTE di AZZURROPOLI ti dà il SALVADANAIO.", es = "La tienda de premios junto al CASINO de CIUDAD AZULONA cambia fichas por POKéMON: ABRA Nv.7 (120 fichas), CLEFAIRY Nv.12 (750), PINSIR Nv.18 (2500), DRATINI Nv.24 (4600), PORYGON Nv.18 (6500). Un hombre del RESTAURANTE de CIUDAD AZULONA te da el MONEDERO.", zh = "游戏城隔壁的奖品柜台可以用代币换宝可梦：凯西 Lv7（120 枚）、皮皮 Lv12（750）、凯罗斯 Lv18（2500）、迷你龙 Lv24（4600）、多边兽 Lv18（6500）。玉虹市餐厅里有个人会给你代币盒。"),
    "LEGENDARY POKéMON" to Tr(ja = "でんせつの ポケモン", fr = "POKéMON LEGENDAIRES", de = "LEGENDÄRE POKéMON", it = "POKéMON LEGGENDARI", es = "POKéMON LEGENDARIOS", zh = "传说的宝可梦"),
    "ARTICUNO" to Tr(ja = "フリーザー", fr = "ARTIKODIN", de = "ARKTOS", it = "ARTICUNO", es = "ARTICUNO", zh = "急冻鸟"),
    "Between FUCHSIA CITY and CINNABAR ISLAND." to Tr(ja = "セキチクシティと グレンじまの あいだ。", fr = "Entre PARMANIE et CRAMOIS'ILE.", de = "Zwischen FUCHSANIA CITY und der ZINNOBERINSEL.", it = "Tra FUCSIAPOLI e l'ISOLA CANNELLA.", es = "Entre CIUDAD FUCSIA e ISLA CANELA.", zh = "浅红市与红莲岛之间。"),
    "The bottom of the SEAFOAM ISLANDS. Push boulders with STRENGTH to slow the currents." to Tr(ja = "ふたごじまの いちばん した。 かいりきで いわを おとして みずの ながれを ゆるめます。", fr = "Au fond des ILES ECUME. Poussez des rochers avec FORCE pour ralentir les courants.", de = "Ganz unten in den SEESCHAUMINSELN. Schieb mit STÄRKE Felsen hinein, um die Strömung zu bremsen.", it = "Il fondo delle ISOLE SPUMARINE. Spingi i massi con FORZA per rallentare le correnti.", es = "El fondo de las ISLAS ESPUMA. Empuja rocas con FUERZA para frenar las corrientes.", zh = "双子岛最底层。用怪力推石头可以减缓水流。"),
    "ZAPDOS" to Tr(ja = "サンダー", fr = "ELECTHOR", de = "ZAPDOS", it = "ZAPDOS", es = "ZAPDOS", zh = "闪电鸟"),
    "An abandoned building." to Tr(ja = "つかわれていない たてもの。", fr = "Un bâtiment abandonné.", de = "Ein verlassenes Gebäude.", it = "Un edificio abbandonato.", es = "Un edificio abandonado.", zh = "一栋废弃建筑。"),
    "The POWER PLANT - SURF from ROUTE 10." to Tr(ja = "むじんはつでんしょ。 10ばん どうろから なみのりで いきます。", fr = "La CENTRALE : SURF depuis la ROUTE 10.", de = "Das KRAFTWERK: mit SURFER ab ROUTE 10.", it = "La CENTRALE ELETTRICA: usa SURF dal PERCORSO 10.", es = "La CENTRAL ENERGÍA: usa SURF desde la RUTA 10.", zh = "无人发电厂——从 １０号道路用冲浪过去。"),
    "MOLTRES" to Tr(ja = "ファイヤー", fr = "SULFURA", de = "LAVADOS", it = "MOLTRES", es = "MOLTRES", zh = "火焰鸟"),
    "A volcano on the SEVII ISLANDS." to Tr(ja = "ななしまの かざん。", fr = "Un volcan des ILES SEVII.", de = "Ein Vulkan auf SEVII EILAND.", it = "Un vulcano del SETTIPELAGO.", es = "Un volcán de ARCHI7.", zh = "七之岛上的一座火山。"),
    "The top of MT. EMBER on ONE ISLAND." to Tr(ja = "1のしまの ともしびやまの ちょうじょう。", fr = "Le sommet du MONT BRAISE, sur l'ILE 1.", de = "Der Gipfel des GLUTBERGS auf EILAND EINS.", it = "La cima del MONTE BRACE, a PRIMISOLA.", es = "La cima del MT. ASCUAS, en ISLA PRIMA.", zh = "一之岛的灯火山山顶。"),
    "MEWTWO" to Tr(ja = "ミュウツー", fr = "MEWTWO", de = "MEWTU", it = "MEWTWO", es = "MEWTWO", zh = "超梦"),
    "Post-game, near CERULEAN CITY." to Tr(ja = "クリアごに ハナダシティの ちかく。", fr = "Après la LIGUE, près d'AZURIA.", de = "Nach dem Abspann, nahe AZURIA CITY.", it = "Dopo la LEGA, vicino a CELESTOPOLI.", es = "Tras la LIGA, cerca de CIUDAD CELESTE.", zh = "通关后，华蓝市附近。"),
    "The bottom of CERULEAN CAVE, which opens after the SEVII ISLANDS story is finished." to Tr(ja = "ハナダのどうくつの いちばん おく。 ななしまの ものがたりが おわると はいれます。", fr = "Au fond de la CAVERNE AZUREE, ouverte une fois l'histoire des ILES SEVII terminée.", de = "Ganz unten in der AZURIA-HÖHLE, die nach der Geschichte auf SEVII EILAND öffnet.", it = "Il fondo della GROTTA CELESTE, che si apre finita la storia del SETTIPELAGO.", es = "El fondo de la CUEVA CELESTE, que se abre al terminar la historia de ARCHI7.", zh = "华蓝洞窟最底层，七之岛剧情结束后才会开放。"),
    "SNORLAX" to Tr(ja = "カビゴン", fr = "RONFLEX", de = "RELAXO", it = "SNORLAX", es = "SNORLAX", zh = "卡比兽"),
    "Sleeping in the way." to Tr(ja = "みちを ふさいで ねている。", fr = "Il dort en travers du chemin.", de = "Schläft mitten im Weg.", it = "Dorme in mezzo alla strada.", es = "Duerme en mitad del camino.", zh = "睡在路上挡道。"),
    "Two block ROUTE 12 and ROUTE 16. Wake them with the POKé FLUTE." to Tr(ja = "12ばん どうろと 16ばん どうろを 1ぴきずつ ふさいでいます。 ポケモンのふえで おこします。", fr = "Deux bloquent la ROUTE 12 et la ROUTE 16. Réveillez-les avec la POKéFLUTE.", de = "Zwei blockieren ROUTE 12 und ROUTE 16. Weck sie mit der POKéFLÖTE.", it = "Due bloccano il PERCORSO 12 e il PERCORSO 16. Svegliali con il POKé FLAUTO.", es = "Dos bloquean la RUTA 12 y la RUTA 16. Despiértalos con la POKé FLAUTA.", zh = "两头分别堵住 １２号道路和 １６号道路。用宝可梦之笛唤醒。"),
    "EARLY GAME" to Tr(ja = "はじめの ほう", fr = "DEBUT DU JEU", de = "SPIELBEGINN", it = "INIZIO DEL GIOCO", es = "PRINCIPIO DEL JUEGO", zh = "前期"),
    "An old man blocks the road north of VIRIDIAN" to Tr(ja = "トキワの きたで おじいさんが みちを ふさいでいる", fr = "Un vieil homme bloque la route au nord de JADIELLE", de = "Ein alter Mann blockiert den Weg nördlich von VERTANIA CITY", it = "Un vecchio blocca la strada a nord di SMERALDOPOLI", es = "Un anciano bloquea el camino al norte de CIUDAD VERDE", zh = "常磐北边的路被一位老人挡着"),
    "PROF. OAK is waiting for something from VIRIDIAN CITY." to Tr(ja = "オーキドはかせは トキワシティから とどく ものを まっています。", fr = "Le PROF. CHEN attend quelque chose de JADIELLE.", de = "PROF. EICH wartet auf etwas aus VERTANIA CITY.", it = "Il PROF. OAK aspetta qualcosa da SMERALDOPOLI.", es = "El PROF. OAK espera algo de CIUDAD VERDE.", zh = "大木博士在等常磐市的一件东西。"),
    "Pick up OAK's PARCEL at the VIRIDIAN CITY POKé MART and deliver it to PROF. OAK in PALLET TOWN. He moves after that." to Tr(ja = "トキワシティの フレンドリィショップで おとどけものを うけとり、 マサラタウンの オーキドはかせに とどけます。 そのあと おじいさんは どいて くれます。", fr = "Prenez le COLIS CHEN à la BOUTIQUE POKéMON de JADIELLE et apportez-le au PROF. CHEN à BOURG PALETTE. Ensuite, il s'écarte.", de = "Hol EICHs PAKET im POKéMON-SUPERMARKT von VERTANIA CITY und bring es PROF. EICH in ALABASTIA. Danach geht er aus dem Weg.", it = "Ritira il PACCO di OAK al POKéMON-MARKET di SMERALDOPOLI e consegnalo al PROF. OAK a BIANCAVILLA. Dopo, lui si sposta.", es = "Recoge el CORREO de OAK en la TIENDA POKéMON de CIUDAD VERDE y llévaselo al PROF. OAK en PUEBLO PALETA. Después, se aparta.", zh = "去常磐市的商店取大木的包裹，送到真新镇的大木博士手上，他就让开了。"),
    "VIRIDIAN CITY's gym is locked" to Tr(ja = "トキワシティの ジムが しまっている", fr = "L'ARENE de JADIELLE est fermée", de = "Die ARENA von VERTANIA CITY ist zu", it = "La PALESTRA di SMERALDOPOLI è chiusa", es = "El GIMNASIO de CIUDAD VERDE está cerrado", zh = "常磐市的道馆锁着"),
    "Come back much later." to Tr(ja = "ずっと あとで もどって こよう。", fr = "Revenez bien plus tard.", de = "Komm viel später wieder.", it = "Torna molto più tardi.", es = "Vuelve mucho más tarde.", zh = "很久以后再来。"),
    "It's the last gym - it opens once you have the other seven badges." to Tr(ja = "さいごの ジムです。 ほかの 7つの バッジを そろえると ひらきます。", fr = "C'est la dernière ARENE : elle ouvre quand vous avez les sept autres BADGES.", de = "Das ist die letzte ARENA - sie öffnet, wenn du die anderen sieben ORDEN hast.", it = "È l'ultima PALESTRA: si apre quando hai le altre sette MEDAGLIE.", es = "Es el último GIMNASIO: se abre cuando tienes las otras siete MEDALLAS.", zh = "这是最后一个道馆——拿到另外七枚徽章后才会开。"),
    "Where's the S.S. TICKET?" to Tr(ja = "ふねのチケットは どこ?", fr = "Où est le PASSE BATEAU ?", de = "Wo ist das BOOTSTICKET?", it = "Dov'è il BIGL. NAVE?", es = "¿Dónde está el TICKET BARCO?", zh = "船票在哪？"),
    "Cross the bridge north of CERULEAN CITY." to Tr(ja = "ハナダシティの きたの はしを わたろう。", fr = "Traversez le pont au nord d'AZURIA.", de = "Überquere die Brücke nördlich von AZURIA CITY.", it = "Attraversa il ponte a nord di CELESTOPOLI.", es = "Cruza el puente al norte de CIUDAD CELESTE.", zh = "穿过华蓝市北边的桥。"),
    "BILL gives it to you after you help him in his cottage at the end of ROUTE 25, north of CERULEAN CITY." to Tr(ja = "ハナダシティの きた、 25ばん どうろの さきの こやで マサキを たすけると くれます。", fr = "LEO vous le donne une fois que vous l'avez aidé chez lui, au bout de la ROUTE 25, au nord d'AZURIA.", de = "BILL gibt es dir, nachdem du ihm in seinem Haus am Ende von ROUTE 25 nördlich von AZURIA CITY geholfen hast.", it = "BILL te lo dà dopo che lo aiuti nella sua casa in fondo al PERCORSO 25, a nord di CELESTOPOLI.", es = "BILL te lo da cuando le ayudas en su casa al final de la RUTA 25, al norte de CIUDAD CELESTE.", zh = "在华蓝市北边、25号道路尽头的小屋帮完正辉，他会给你。"),
    "ROCK TUNNEL is pitch black" to Tr(ja = "イワヤマトンネルが まっくら", fr = "La GROTTE est plongée dans le noir", de = "Im FELSTUNNEL ist es stockdunkel", it = "Il TUNNEL ROCCIOSO è buio pesto", es = "El TÚNEL ROCA está a oscuras", zh = "岩山隧道里一片漆黑"),
    "An HM helps, but it's optional." to Tr(ja = "ひでんわざが やくに たつけど なくても だいじょうぶ。", fr = "Une CS aide, mais elle n'est pas obligatoire.", de = "Eine VM hilft, ist aber kein Muss.", it = "Una MN aiuta, ma non è obbligatoria.", es = "Una MO ayuda, pero no es obligatoria.", zh = "有个秘传能帮上忙，但不是必需。"),
    "FLASH lights it up (HM05, see WHERE IS), but you can walk through without it." to Tr(ja = "フラッシュで あかるく なります (ひでんマシン05、 「どこに ある」を みてね)。 なくても とおりぬけ られます。", fr = "FLASH l'éclaire (CS05, voir OÙ TROUVER), mais on peut la traverser sans.", de = "BLITZ erhellt ihn (VM05, siehe FUNDORTE), aber du kommst auch ohne durch.", it = "FLASH lo illumina (MN05, vedi DOV'È), ma puoi attraversarlo anche senza.", es = "DESTELLO lo ilumina (MO05, ver DÓNDE ESTÁ), pero puedes cruzarlo sin él.", zh = "用闪光可以照亮（秘传学习器０５，见「在哪里」），不过不开灯也能走过去。"),
    "MID GAME" to Tr(ja = "ちゅうばん", fr = "MILIEU DU JEU", de = "SPIELMITTE", it = "METÀ GIOCO", es = "MITAD DEL JUEGO", zh = "中期"),
    "How do I get into SAFFRON CITY?" to Tr(ja = "ヤマブキシティに はいるには?", fr = "Comment entrer à SAFRANIA ?", de = "Wie komme ich nach SAFFRONIA CITY?", it = "Come entro a ZAFFERANOPOLI?", es = "¿Cómo entro en CIUDAD AZAFRÁN?", zh = "怎么进金黄市？"),
    "They'd like a drink - ask around CELADON CITY." to Tr(ja = "のみものが ほしい みたい。 タマムシシティで さがそう。", fr = "Ils ont soif : renseignez-vous à CELADOPOLE.", de = "Sie hätten gern etwas zu trinken - hör dich in PRISMANIA CITY um.", it = "Vorrebbero bere qualcosa: chiedi in giro ad AZZURROPOLI.", es = "Quieren beber algo: pregunta por CIUDAD AZULONA.", zh = "他们想喝点东西——去玉虹市打听。"),
    "The gate guards are thirsty. Get TEA from the old woman on the ground floor of the CELADON CONDOMINIUMS and any guard lets you through." to Tr(ja = "ゲートの けいびいんは のどが かわいています。 タマムシマンション 1かいの おばあさんに おちゃを もらえば どの けいびいんも とおして くれます。", fr = "Les gardes des postes ont soif. Obtenez du THE auprès de la vieille dame au rez-de-chaussée du MANOIR CELADON : n'importe quel garde vous laissera passer.", de = "Die Torwachen haben Durst. Hol dir TEE von der alten Frau im Erdgeschoss der PRISMANIA-VILLA, dann lässt dich jede Wache durch.", it = "Le guardie dei varchi hanno sete. Fatti dare il TÈ dalla vecchietta al pianterreno di VILLAZZURRA e qualsiasi guardia ti farà passare.", es = "Los guardias de las casetas tienen sed. Consigue TÉ de la anciana de la planta baja de la MANSIÓN AZULONA y cualquier guardia te dejará pasar.", zh = "关卡守卫口渴了。去玉虹公寓一楼找老奶奶拿茶，随便哪个守卫都会放行。"),
    "I can't identify the ghosts in POKéMON TOWER" to Tr(ja = "ポケモンタワーの ゆうれいの しょうたいが わからない", fr = "Impossible d'identifier les spectres de la TOUR POKéMON", de = "Ich erkenne die Geister im POKéMON TURM nicht", it = "Non riesco a riconoscere i fantasmi della TORRE POKéMON", es = "No identifico a los fantasmas de la TORRE POKéMON", zh = "宝可梦塔的幽灵我认不出来"),
    "TEAM ROCKET has it, somewhere in CELADON CITY." to Tr(ja = "タマムシシティの どこかで ロケットだんが もっています。", fr = "La TEAM ROCKET l'a, quelque part à CELADOPOLE.", de = "TEAM ROCKET hat es, irgendwo in PRISMANIA CITY.", it = "Ce l'ha il TEAM ROCKET, da qualche parte ad AZZURROPOLI.", es = "Lo tiene el TEAM ROCKET, en algún lugar de CIUDAD AZULONA.", zh = "在火箭队手上，就在玉虹市某处。"),
    "You need the SILPH SCOPE. It's on ROCKET HIDEOUT B4F, under the CELADON GAME CORNER - a switch behind a poster opens the entrance." to Tr(ja = "シルフスコープが ひつようです。 タマムシの ゲームコーナーの したの ロケットだんちかアジトの ちか4かいに あります。 ポスターの うらの スイッチで いりぐちが ひらきます。", fr = "Il vous faut le SCOPE SYLPHE. Il est au 4e sous-sol du REPAIRE ROCKET, sous le CASINO de CELADOPOLE : un bouton derrière une affiche ouvre l'entrée.", de = "Du brauchst das SILPH SCOPE. Es ist im 4. Untergeschoss des ROCKET HQ unter der SPIELHALLE von PRISMANIA CITY - ein Schalter hinter einem Poster öffnet den Eingang.", it = "Ti serve la SPETTROSONDA. È al 4º sotterraneo del RIFUGIO ROCKET, sotto il CASINÒ di AZZURROPOLI: un interruttore dietro un poster apre l'ingresso.", es = "Necesitas el SCOPE SILPH. Está en el sótano 4 de la GUARIDA ROCKET, bajo el CASINO de CIUDAD AZULONA: un interruptor tras un póster abre la entrada.", zh = "需要西尔佛检视镜。它在玉虹游戏城地下的火箭队秘密基地地下4层——海报后面的开关能打开入口。"),
    "The hideout's elevator won't move" to Tr(ja = "アジトの エレベーターが うごかない", fr = "L'ascenseur du repaire ne marche pas", de = "Der Aufzug im Versteck fährt nicht", it = "L'ascensore del rifugio non si muove", es = "El ascensor de la guarida no funciona", zh = "秘密基地的电梯不动"),
    "Someone downstairs has a key." to Tr(ja = "したの かいの だれかが カギを もっています。", fr = "Quelqu'un plus bas a une clé.", de = "Jemand weiter unten hat einen Schlüssel.", it = "Qualcuno ai piani di sotto ha una chiave.", es = "Alguien en un piso inferior tiene una llave.", zh = "楼下有人有钥匙。"),
    "It needs the LIFT KEY, which a ROCKET on B4F drops. Take the stairs down to reach him." to Tr(ja = "エレベータのカギが ひつようです。 ちか4かいの ロケットだんいんが おとします。 かいだんで おりて いこう。", fr = "Il faut la CLE ASC., que laisse tomber un ROCKET au 4e sous-sol. Descendez par les escaliers pour l'atteindre.", de = "Er braucht den LIFTÖFFNER, den ein ROCKET im 4. Untergeschoss fallen lässt. Nimm die Treppe nach unten zu ihm.", it = "Serve la CHIAVE ASC., che un ROCKET al 4º sotterraneo lascia cadere. Scendi dalle scale per raggiungerlo.", es = "Necesita la LL. ASCENSOR, que suelta un ROCKET del sótano 4. Baja por las escaleras para llegar hasta él.", zh = "需要电梯钥匙，地下4层的一个火箭队会掉。走楼梯下去找他。"),
    "A SNORLAX blocks the road" to Tr(ja = "カビゴンが みちを ふさいでいる", fr = "Un RONFLEX bloque la route", de = "Ein RELAXO blockiert den Weg", it = "Uno SNORLAX blocca la strada", es = "Un SNORLAX bloquea el camino", zh = "卡比兽挡住去路"),
    "Something in LAVENDER TOWN wakes it." to Tr(ja = "シオンタウンの なにかで おこせます。", fr = "Quelque chose à LAVANVILLE le réveille.", de = "Etwas aus LAVANDIA weckt es.", it = "Qualcosa a LAVANDONIA lo sveglia.", es = "Algo de PUEBLO LAVANDA lo despierta.", zh = "紫苑镇有办法唤醒它。"),
    "Rescue MR. FUJI from the top of POKéMON TOWER; he gives you the POKé FLUTE at his house in LAVENDER TOWN." to Tr(ja = "ポケモンタワーの てっぺんで フジろうじんを たすけると、 シオンタウンの いえで ポケモンのふえを くれます。", fr = "Sauvez MR. FUJI au sommet de la TOUR POKéMON ; il vous donne la POKéFLUTE chez lui, à LAVANVILLE.", de = "Rette MR. FUJI oben im POKéMON TURM; er gibt dir die POKéFLÖTE in seinem Haus in LAVANDIA.", it = "Salva MR. FUJI in cima alla TORRE POKéMON; ti darà il POKé FLAUTO a casa sua, a LAVANDONIA.", es = "Rescata al SR. FUJI en lo alto de la TORRE POKéMON; te dará la POKé FLAUTA en su casa de PUEBLO LAVANDA.", zh = "从宝可梦塔顶层救出富士老人，他会在紫苑镇的家里给你宝可梦之笛。"),
    "How do I get to FUCHSIA CITY?" to Tr(ja = "セキチクシティへ いくには?", fr = "Comment aller à PARMANIE ?", de = "Wie komme ich nach FUCHSANIA CITY?", it = "Come arrivo a FUCSIAPOLI?", es = "¿Cómo llego a CIUDAD FUCSIA?", zh = "怎么去浅红市？"),
    "There are two ways - one needs wheels." to Tr(ja = "みちは 2つ。 かたほうは じてんしゃが いります。", fr = "Il y a deux chemins : l'un demande des roues.", de = "Es gibt zwei Wege - einer braucht Räder.", it = "Ci sono due strade: una richiede le ruote.", es = "Hay dos caminos: uno requiere ruedas.", zh = "两条路，其中一条得靠车。"),
    "Ride CYCLING ROAD south from CELADON CITY (BICYCLE needed), or go down ROUTES 12-15 from LAVENDER TOWN after waking the SNORLAX." to Tr(ja = "タマムシシティから サイクリング ロードを みなみへ (じてんしゃが ひつよう)。 または カビゴンを おこしてから シオンタウンから 12から15ばん どうろを くだります。", fr = "Descendez la PISTE CYCLABLE au sud de CELADOPOLE (BICYCLETTE requise), ou suivez les ROUTES 12 à 15 depuis LAVANVILLE après avoir réveillé le RONFLEX.", de = "Fahr den RADWEG südlich von PRISMANIA CITY hinunter (FAHRRAD nötig) oder geh nach dem Wecken von RELAXO ab LAVANDIA die ROUTEN 12-15 entlang.", it = "Percorri la PISTA CICLABILE a sud di AZZURROPOLI (serve la BICICLETTA), oppure scendi lungo i PERCORSI 12-15 da LAVANDONIA dopo aver svegliato SNORLAX.", es = "Baja por el CAMINO DE BICIS al sur de CIUDAD AZULONA (hace falta la BICICLETA) o recorre las RUTAS 12-15 desde PUEBLO LAVANDA tras despertar a SNORLAX.", zh = "从玉虹市走自行车道南下（需要自行车），或者唤醒卡比兽后从紫苑镇走 12-15号道路。"),
    "SILPH CO.'s doors are locked" to Tr(ja = "シルフカンパニーの ドアが あかない", fr = "Les portes de la SYLPHE SARL sont fermées", de = "Die Türen der SILPH CO. sind verschlossen", it = "Le porte della SILPH SpA sono chiuse", es = "Las puertas de SILPH S.A. están cerradas", zh = "西尔佛公司的门锁着"),
    "Somewhere in the middle floors." to Tr(ja = "まんなかあたりの かいの どこか。", fr = "Quelque part dans les étages du milieu.", de = "Irgendwo in den mittleren Stockwerken.", it = "Da qualche parte ai piani intermedi.", es = "En algún piso intermedio.", zh = "在中间某一层。"),
    "Find the CARD KEY on 5F; it opens every locked door in the building." to Tr(ja = "5かいで カードキーを みつけよう。 ビルの しまった ドアが ぜんぶ あきます。", fr = "Trouvez la CARTE MAGN. au 4e étage ; elle ouvre toutes les portes fermées du bâtiment.", de = "Finde den TÜRÖFFNER im 4. Stock; er öffnet jede verschlossene Tür im Gebäude.", it = "Trova l'APRIPORTA al 4º piano: apre tutte le porte chiuse dell'edificio.", es = "Encuentra la LL.MAGNÉTICA en la planta 4: abre todas las puertas cerradas del edificio.", zh = "在 5楼找到钥匙卡，它能打开楼里所有上锁的门。"),
    "LATE GAME" to Tr(ja = "おわりの ほう", fr = "FIN DU JEU", de = "SPIELENDE", it = "FINE DEL GIOCO", es = "FINAL DEL JUEGO", zh = "后期"),
    "CINNABAR ISLAND's gym is locked" to Tr(ja = "グレンじまの ジムが しまっている", fr = "L'ARENE de CRAMOIS'ILE est fermée", de = "Die ARENA der ZINNOBERINSEL ist zu", it = "La PALESTRA dell'ISOLA CANNELLA è chiusa", es = "El GIMNASIO de ISLA CANELA está cerrado", zh = "红莲岛的道馆锁着"),
    "Search the burned-out building." to Tr(ja = "やけた たてものを しらべよう。", fr = "Fouillez le bâtiment incendié.", de = "Durchsuche das ausgebrannte Gebäude.", it = "Esplora l'edificio bruciato.", es = "Registra el edificio quemado.", zh = "去那栋烧毁的建筑里找。"),
    "The SECRET KEY is in the basement of the POKéMON MANSION on the same island." to Tr(ja = "ひみつのカギは おなじ しまの ポケモンやしきの ちかに あります。", fr = "La CLE SECRETE est au sous-sol du MANOIR POKéMON, sur la même île.", de = "Der ?-ÖFFNER liegt im Keller des POKéMON-HAUSES auf derselben Insel.", it = "La CHIAVE SEGR. è nel seminterrato di VILLA POKéMON, sulla stessa isola.", es = "La LL. SECRETA está en el sótano de la MANSIÓN POKéMON, en la misma isla.", zh = "秘密钥匙在同岛宝可梦屋的地下室。"),
    "VICTORY ROAD's boulders" to Tr(ja = "チャンピオンロードの いわ", fr = "Les rochers de la ROUTE VICTOIRE", de = "Die Felsen der SIEGESSTRASSE", it = "I massi della VIA VITTORIA", es = "Las rocas de CALLE VICTORIA", zh = "冠军之路的巨石"),
    "An HM moves them." to Tr(ja = "ひでんわざで うごかせます。", fr = "Une CS les déplace.", de = "Eine VM bewegt sie.", it = "Una MN li sposta.", es = "Una MO las mueve.", zh = "用秘传招式移开。"),
    "Teach STRENGTH and push boulders onto the floor switches to open the way." to Tr(ja = "かいりきを おぼえさせ、 いわを ゆかの スイッチに のせて みちを ひらきます。", fr = "Apprenez FORCE et poussez les rochers sur les interrupteurs au sol pour ouvrir le passage.", de = "Bring STÄRKE bei und schieb Felsen auf die Bodenschalter, um den Weg zu öffnen.", it = "Insegna FORZA e spingi i massi sugli interruttori a terra per aprire la strada.", es = "Enseña FUERZA y empuja las rocas sobre los interruptores del suelo para abrir el paso.", zh = "教怪力，把巨石推到地面开关上就能开路。"),
    "POST-GAME" to Tr(ja = "クリアご", fr = "APRES LA LIGUE", de = "NACH DEM ABSPANN", it = "DOPO LA LEGA", es = "TRAS LA LIGA", zh = "通关后"),
    "How do I get the National Dex?" to Tr(ja = "ぜんこくずかんは どうやって もらう?", fr = "Comment obtenir le POKéDEX NATIONAL ?", de = "Wie bekomme ich den NATIONALEN POKéDEX?", it = "Come ottengo il POKéDEX NAZIONALE?", es = "¿Cómo consigo el POKéDEX NACIONAL?", zh = "怎么拿到全国图鉴？"),
    "Finish the League and keep catching." to Tr(ja = "ポケモンリーグを クリアして つかまえつづけよう。", fr = "Terminez la LIGUE et continuez à capturer.", de = "Schließ die LIGA ab und fang weiter.", it = "Completa la LEGA e continua a catturare.", es = "Termina la LIGA y sigue capturando.", zh = "打完联盟后继续捕捉。"),
    "Beat the POKéMON LEAGUE, catch 60 kinds of KANTO POKéMON, then talk to PROF. OAK." to Tr(ja = "ポケモンリーグで ゆうしょうし、 カントーの ポケモンを 60しゅるい つかまえて オーキドはかせと はなします。", fr = "Battez la LIGUE POKéMON, attrapez 60 espèces de POKéMON de KANTO, puis parlez au PROF. CHEN.", de = "Besiege die POKéMON LIGA, fang 60 KANTO-POKéMON-Arten und sprich dann mit PROF. EICH.", it = "Vinci la LEGA POKéMON, cattura 60 specie di POKéMON di KANTO, poi parla col PROF. OAK.", es = "Vence en la LIGA POKéMON, atrapa 60 especies de POKéMON de KANTO y habla con el PROF. OAK.", zh = "战胜宝可梦联盟，捕捉 60 种关都宝可梦，再去找大木博士。"),
    "How do I reach the SEVII ISLANDS?" to Tr(ja = "ななしまへ いくには?", fr = "Comment aller aux ILES SEVII ?", de = "Wie komme ich nach SEVII EILAND?", it = "Come arrivo al SETTIPELAGO?", es = "¿Cómo llego a ARCHI7?", zh = "怎么去七之岛？"),
    "After the seventh badge, someone on CINNABAR ISLAND." to Tr(ja = "7つめの バッジの あと、 グレンじまに いる だれか。", fr = "Après le septième BADGE, quelqu'un à CRAMOIS'ILE.", de = "Nach dem siebten ORDEN: jemand auf der ZINNOBERINSEL.", it = "Dopo la settima MEDAGLIA, qualcuno sull'ISOLA CANNELLA.", es = "Tras la séptima MEDALLA, alguien de ISLA CANELA.", zh = "拿到第七枚徽章后，红莲岛会有人带你过去。"),
    "After beating BLAINE, BILL is waiting at CINNABAR ISLAND and takes you to ONE ISLAND." to Tr(ja = "カツラに かつと グレンじまで マサキが まっていて 1のしまへ つれていって くれます。", fr = "Après votre victoire contre AUGUSTE, LEO vous attend à CRAMOIS'ILE et vous emmène sur l'ILE 1.", de = "Nach dem Sieg über PYRO wartet BILL auf der ZINNOBERINSEL und bringt dich nach EILAND EINS.", it = "Dopo aver battuto BLAINE, BILL ti aspetta sull'ISOLA CANNELLA e ti porta a PRIMISOLA.", es = "Tras vencer a BLAINE, BILL te espera en ISLA CANELA y te lleva a ISLA PRIMA.", zh = "击败夏伯后，正辉会在红莲岛等你，带你去一之岛。"),
    "CERULEAN CAVE is guarded" to Tr(ja = "ハナダのどうくつに みはりが いる", fr = "La CAVERNE AZUREE est gardée", de = "Die AZURIA-HÖHLE wird bewacht", it = "La GROTTA CELESTE è sorvegliata", es = "La CUEVA CELESTE está vigilada", zh = "华蓝洞窟有人把守"),
    "Two gems for CELIO." to Tr(ja = "ニシキに 2つの ほうせきを。", fr = "Deux pierres précieuses pour CILEO.", de = "Zwei Edelsteine für CELIO.", it = "Due gemme per CELIO.", es = "Dos gemas para CELIO.", zh = "给塞莉奥两颗宝石。"),
    "Finish the SEVII ISLANDS story: bring the RUBY (MT. EMBER) and SAPPHIRE to CELIO on ONE ISLAND." to Tr(ja = "ななしまの ものがたりを おえよう: ルビー (ともしびやま) と サファイアを 1のしまの ニシキに とどけます。", fr = "Terminez l'histoire des ILES SEVII : apportez le RUBIS (MONT BRAISE) et le SAPHIR à CILEO sur l'ILE 1.", de = "Beende die Geschichte auf SEVII EILAND: Bring den RUBIN (GLUTBERG) und den SAPHIR zu CELIO auf EILAND EINS.", it = "Finisci la storia del SETTIPELAGO: porta il RUBINO (MONTE BRACE) e lo ZAFFIRO a CELIO a PRIMISOLA.", es = "Termina la historia de ARCHI7: lleva el RUBÍ (MT. ASCUAS) y el ZAFIRO a CELIO en ISLA PRIMA.", zh = "完成七之岛剧情：把红宝石（灯火山）和蓝宝石交给一之岛的塞莉奥。"),
